typedef int nvlMsg;
typedef void (*callbackType)(int);
struct nvlMsgQueue { int sema; nvlMsg *array; };
struct nvlStream;
struct ThreadParam { int status; void (*entry)(void *); void *stack; int stackSize; void *gpReg; int initPriority, currentPriority; unsigned int attr, option; int waitType, waitId, wakeupCount; };
enum { NVLSTREAM_MSG_NUM=8, CDVD_MSG_NUM=1, NVL_MAX_STREAM_NUM=8, NVL_MSG_SHUTDOWN=0, NVL_STREAM_MAX_TRIES=3600, INTC_VBLANK_S=2, SCECdEXIT=1 };
struct nvlStreamSystemData_t {
  char *threadStack; ThreadParam threadParam; int threadID, mainThreadID;
  nvlMsgQueue threadMsgQueue; nvlMsg msg[NVLSTREAM_MSG_NUM];
  nvlMsgQueue cdvdMsgQueue; nvlMsg cdvdMsg[CDVD_MSG_NUM];
  int vblankHandlerID, VBWasEnabled, vblankSema;
  nvlStream *pStream[NVL_MAX_STREAM_NUM]; int streamList[NVL_MAX_STREAM_NUM];
  callbackType prevCDVDCallback;
};
extern nvlStreamSystemData_t nvlStreamSystemData;
extern int nvlStreamSystemInitialized, nvlStreamSystemLibsInitialized;
extern volatile int nvlStreamSystemThreadIsRunning;
extern void (*nvlStreamFreeFunc)(void *);
void nvlStreamDestroy(nvlStream *); void nvlSendMsg(nvlMsgQueue *, nvlMsg, nvlStream *);
void nvlWaitForVB(); void nvlDestroyMsgQueue(nvlMsgQueue *);
